\documentclass{article}
\usepackage[paperwidth=841mm,paperheight=1189mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{colortbl}
\pagestyle{empty}

% ── Data-Report Dark Color Theme ──
\definecolor{primary}{HTML}{0B1120}      % deep navy background
\definecolor{cardbg}{HTML}{131F35}       % card background (slightly lighter)
\definecolor{cardbg2}{HTML}{182840}      % alt card background
\definecolor{blueaccent}{HTML}{3B82F6}   % electric blue
\definecolor{greenaccent}{HTML}{10B981}  % vibrant green
\definecolor{amberaccent}{HTML}{F59E0B}  % warm amber
\definecolor{textlight}{HTML}{E2E8F0}    % light text
\definecolor{textmuted}{HTML}{94A3B8}    % muted text
\definecolor{textbright}{HTML}{F8FAFC}   % bright white text
\definecolor{tableheader}{HTML}{1E3A5F}  % table header dark blue
\definecolor{airow}{HTML}{0F3828}        % AI row subtle green tint
\definecolor{nonairow}{HTML}{131F35}     % non-AI row (same as cardbg)
\definecolor{tablerule}{HTML}{1E3A5F}    % table rule color

\pagecolor{primary}
\color{textlight}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=6pt, parsep=2pt, topsep=2pt,
  label={\color{blueaccent}$\blacktriangleright$}}

% ── Card styles for dark theme ──
\tcbset{
  bluecard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{blueaccent},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{blueaccent},
    coltitle=blueaccent, colbacktitle=cardbg2,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={blueaccent!50},
    valign=top, drop shadow={opacity=0.25, shadow={2pt}{2pt}{black}},
  },
  greencard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{greenaccent},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{greenaccent},
    coltitle=greenaccent, colbacktitle=cardbg2,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={greenaccent!50},
    valign=top, drop shadow={opacity=0.25, shadow={2pt}{2pt}{black}},
  },
  ambercard/.style={
    enhanced, arc=0pt, boxrule=0pt, colback=cardbg,
    borderline west={5pt}{0pt}{amberaccent},
    left=16pt, right=14pt, top=4pt, bottom=4pt,
    fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{amberaccent},
    coltitle=amberaccent, colbacktitle=cardbg2,
    toptitle=6pt, bottomtitle=6pt,
    titlerule=2pt, titlerule style={amberaccent!50},
    valign=top, drop shadow={opacity=0.25, shadow={2pt}{2pt}{black}},
  },
  statcard/.style={
    enhanced, arc=0pt, boxrule=1pt, colback=cardbg,
    colframe=cardbg2, left=10pt, right=10pt, top=8pt, bottom=8pt,
    valign=center, halign=center,
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=3, rows=20, spacing=0mm},
]

% ══════════════════════════════════════════════════════════════
% TITLE BAR (rows 0-4, span=3)
% ══════════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=cardbg, colframe=cardbg, colupper=textbright,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=12pt, bottom=10pt,
  halign=center, valign=center,
  borderline south={1pt}{0pt}{blueaccent!30},
]{name=title, column=1, span=3, between=top and row4}{
  {\fontsize{62}{76}\selectfont\bfseries\color{textbright} GitHub's Hottest Repos}\\[8pt]
  {\fontsize{38}{48}\selectfont\color{greenaccent}\bfseries AI Agents Dominate the Trending Charts}\\[10pt]
  {\fontsize{24}{30}\selectfont\color{textmuted} A data-driven snapshot of the top 20 trending GitHub repositories \textbar\ Past 24 Hours \textbar\ OSSInsight Analytics}
}

% ══════════════════════════════════════════════════════════════
% STAT BANNER (rows 4-6, span=3) — 5 metric callouts
% ══════════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=cardbg2, boxrule=0pt, arc=0pt,
  left=8pt, right=8pt, top=6pt, bottom=6pt,
  valign=center,
  borderline south={2pt}{0pt}{blueaccent!25},
]{name=stats, column=1, span=3, between=row4 and row6}{
  \centering
  \begin{minipage}[c]{0.19\linewidth}\centering
    {\fontsize{44}{52}\selectfont\bfseries\color{amberaccent}10.6B+}\\[3pt]
    {\fontsize{18}{22}\selectfont\color{textmuted}GitHub Events Tracked}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.19\linewidth}\centering
    {\fontsize{44}{52}\selectfont\bfseries\color{blueaccent}826}\\[3pt]
    {\fontsize{18}{22}\selectfont\color{textmuted}Top Repo Stars (24h)}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.19\linewidth}\centering
    {\fontsize{44}{52}\selectfont\bfseries\color{greenaccent}14 / 20}\\[3pt]
    {\fontsize{18}{22}\selectfont\color{textmuted}AI/Agent Repos {\color{greenaccent}(70\%)}}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.19\linewidth}\centering
    {\fontsize{44}{52}\selectfont\bfseries\color{blueaccent}Python}\\[3pt]
    {\fontsize{18}{22}\selectfont\color{textmuted}Top Language (7 repos)}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.19\linewidth}\centering
    {\fontsize{44}{52}\selectfont\bfseries\color{amberaccent}3,254}\\[3pt]
    {\fontsize{18}{22}\selectfont\color{textmuted}Total Stars (Top 10)}
  \end{minipage}
}

% ══════════════════════════════════════════════════════════════
% TOP-20 TRENDING REPOS TABLE (rows 6-13, span=3) — CENTERPIECE
% ══════════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=0pt,
  left=12pt, right=12pt, top=6pt, bottom=6pt,
  valign=top,
  fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{textbright},
  coltitle=textbright, colbacktitle=cardbg,
  toptitle=6pt, bottomtitle=8pt,
  titlerule=2pt, titlerule style={blueaccent!60},
  borderline west={5pt}{0pt}{greenaccent},
  drop shadow={opacity=0.25, shadow={2pt}{2pt}{black}},
  title={Top 20 Trending Repositories (Past 24 Hours)},
]{name=trendingtable, column=1, span=3, between=row6 and row13}{
  \fontsize{20}{26}\selectfont
  \renewcommand{\arraystretch}{1.5}
  \setlength{\tabcolsep}{8pt}
  \rowcolors{2}{cardbg}{cardbg2}
  \begin{tabular}{r p{180mm} c c c}
    \rowcolor{tableheader}
    {\color{textbright}\bfseries \#} &
    {\color{textbright}\bfseries Repository} &
    {\color{textbright}\bfseries Lang} &
    {\color{textbright}\bfseries Stars} &
    {\color{textbright}\bfseries Forks} \\[2pt]
    \color{amberaccent}\textbf{1} & forrestchang/andrej-karpathy-skills \hfill {\color{greenaccent}\footnotesize $\blacktriangleleft$ AI} & {\textemdash} & 826 & 79 \\
    \color{amberaccent}\textbf{2} & NousResearch/hermes-agent \hfill {\color{greenaccent}\footnotesize $\blacktriangleleft$ AI} & Python & 468 & 102 \\
    \color{amberaccent}\textbf{3} & NawfalMotii79/PLFM\_RADAR & Verilog & 353 & 81 \\
    \color{amberaccent}\textbf{4} & thedotmack/claude-mem \hfill {\color{greenaccent}\footnotesize $\blacktriangleleft$ AI} & TypeScript & 335 & 33 \\
    \color{amberaccent}\textbf{5} & VoltAgent/awesome-design-md \hfill {\color{greenaccent}\footnotesize $\blacktriangleleft$ AI} & HTML & 321 & 49 \\
    \color{amberaccent}\textbf{6} & JuliusBrussee/caveman \hfill {\color{greenaccent}\footnotesize $\blacktriangleleft$ AI} & Python & 237 & 19 \\
    \color{amberaccent}\textbf{7} & multica-ai/multica \hfill {\color{greenaccent}\footnotesize $\blacktriangleleft$ AI} & TypeScript & 139 & 13 \\
    \color{amberaccent}\textbf{8} & safishamsi/graphify \hfill {\color{greenaccent}\footnotesize $\blacktriangleleft$ AI} & Python & 120 & 13 \\
    \color{amberaccent}\textbf{9} & jamiepine/voicebox \hfill {\color{greenaccent}\footnotesize $\blacktriangleleft$ AI} & TypeScript & 100 & 12 \\
    \color{amberaccent}\textbf{10} & lsdefine/GenericAgent \hfill {\color{greenaccent}\footnotesize $\blacktriangleleft$ AI} & Python & 101 & 9 \\
    \color{amberaccent}\textbf{11} & rohitg00/ai-engineering-from-scratch \hfill {\color{greenaccent}\footnotesize $\blacktriangleleft$ AI} & Python & 82 & 19 \\
    \color{amberaccent}\textbf{12} & EvoMap/evolver & JavaScript & 95 & 5 \\
    \color{amberaccent}\textbf{13} & google/magika & Python & 122 & 7 \\
    \color{amberaccent}\textbf{14} & vercel-labs/open-agents \hfill {\color{greenaccent}\footnotesize $\blacktriangleleft$ AI} & TypeScript & 84 & 12 \\
    \color{amberaccent}\textbf{15} & thunderbird/thunderbolt & TypeScript & 82 & 4 \\
    \color{amberaccent}\textbf{16} & alchaincyf/nuwa-skill \hfill {\color{greenaccent}\footnotesize $\blacktriangleleft$ AI} & Python & 67 & 17 \\
    \color{amberaccent}\textbf{17} & BasedHardware/omi \hfill {\color{greenaccent}\footnotesize $\blacktriangleleft$ AI} & Dart & 111 & 72 \\
    \color{amberaccent}\textbf{18} & farion1231/cc-switch & Rust & 77 & 6 \\
    \color{amberaccent}\textbf{19} & SimoneAvogadro/android-reverse-engineering-skill & Shell & 77 & 0 \\
    \color{amberaccent}\textbf{20} & rtk-ai/rtk \hfill {\color{greenaccent}\footnotesize $\blacktriangleleft$ AI} & Rust & 73 & 4
  \end{tabular}
  \vspace{4pt}
  {\fontsize{16}{20}\selectfont\color{textmuted}\hfill$\blacktriangleleft$ AI = AI/Agent-related repository \hfill Composite Score = Stars + Forks + Base Score}
}

% ══════════════════════════════════════════════════════════════
% LANGUAGE BREAKDOWN (rows 13-17, col 1-2)
% ══════════════════════════════════════════════════════════════
\posterbox[
  bluecard, title={Language Distribution},
]{name=language, column=1, span=2, between=row13 and row17}{
  \fontsize{30}{38}\selectfont
  \vspace{4pt}
  \renewcommand{\arraystretch}{1.5}
  \setlength{\tabcolsep}{14pt}
  \begin{tabular}{l c c}
    \rowcolor{tableheader}
    {\color{textbright}\bfseries Language} & {\color{textbright}\bfseries Repos} & {\color{textbright}\bfseries Share} \\[2pt]
    Python & 7 & 35\% \\
    TypeScript & 5 & 25\% \\
    Rust & 2 & 10\% \\
    Verilog & 1 & 5\% \\
    HTML & 1 & 5\% \\
    JavaScript & 1 & 5\% \\
    Dart & 1 & 5\% \\
    Shell & 1 & 5\% \\
    {\textemdash} (none) & 1 & 5\%
  \end{tabular}
  \vspace{6pt}
  {\fontsize{24}{30}\selectfont\color{textmuted} Python + TypeScript = {\color{blueaccent}\textbf{60\%}} of top 20 trending repos.}
}

% ══════════════════════════════════════════════════════════════
% AI VS OTHER SPLIT (rows 13-17, col 3)
% ══════════════════════════════════════════════════════════════
\posterbox[
  greencard, title={AI vs. Other},
]{name=aisplit, column=3, span=1, between=row13 and row17}{
  \fontsize{30}{38}\selectfont
  \vspace{8pt}
  \centering
  {\fontsize{64}{76}\selectfont\bfseries\color{greenaccent}70\%}\\[6pt]
  {\fontsize{28}{34}\selectfont\color{textlight} AI/Agent Repos}\\[4pt]
  {\fontsize{48}{56}\selectfont\bfseries\color{amberaccent}14}\\[2pt]
  {\fontsize{24}{30}\selectfont\color{textmuted} out of 20 trending}\\[12pt]
  \colorbox{greenaccent!25}{\parbox{0.86\linewidth}{\centering\vspace{4pt}
    {\fontsize{20}{24}\selectfont\color{textlight}Autonomous agents, token optimization, memory \& context tools}\vspace{4pt}
  }}
}

% ══════════════════════════════════════════════════════════════
% KEY THEMES (rows 17-20, span=3)
% ══════════════════════════════════════════════════════════════
\posterbox[
  enhanced, colback=cardbg, boxrule=0pt, arc=0pt,
  left=12pt, right=12pt, top=6pt, bottom=6pt,
  valign=top,
  fonttitle=\fontsize{36}{44}\selectfont\bfseries\color{amberaccent},
  coltitle=amberaccent, colbacktitle=cardbg2,
  toptitle=6pt, bottomtitle=8pt,
  titlerule=2pt, titlerule style={amberaccent!50},
  borderline west={5pt}{0pt}{amberaccent},
  drop shadow={opacity=0.25, shadow={2pt}{2pt}{black}},
  title={Key Themes Driving the Trend},
]{name=themes, column=1, span=3, between=row17 and bottom}{
  \fontsize{24}{32}\selectfont
  \begin{minipage}[t]{0.23\linewidth}
    \colorbox{greenaccent!20}{\parbox{0.92\linewidth}{\centering\vspace{4pt}
      {\fontsize{26}{32}\selectfont\bfseries\color{greenaccent} Autonomous\\Coding Agents}\vspace{2pt}
    }}\\[6pt]
    \begin{itemize}[leftmargin=16pt, itemsep=4pt]
      \item multica-ai/multica
      \item vercel-labs/open-agents
      \item lsdefine/GenericAgent
      \item AI writes code, handles issues, executes desktop tasks
    \end{itemize}
  \end{minipage}\hfill
  \begin{minipage}[t]{0.23\linewidth}
    \colorbox{blueaccent!20}{\parbox{0.92\linewidth}{\centering\vspace{4pt}
      {\fontsize{26}{32}\selectfont\bfseries\color{blueaccent} Token\\Optimization}\vspace{2pt}
    }}\\[6pt]
    \begin{itemize}[leftmargin=16pt, itemsep=4pt]
      \item JuliusBrussee/caveman
      \item rtk-ai/rtk
      \item Slash LLM token consumption by 60--90\%
      \item Address cost \& latency
    \end{itemize}
  \end{minipage}\hfill
  \begin{minipage}[t]{0.23\linewidth}
    \colorbox{amberaccent!20}{\parbox{0.92\linewidth}{\centering\vspace{4pt}
      {\fontsize{26}{32}\selectfont\bfseries\color{amberaccent} Memory \& Context\\Management}\vspace{2pt}
    }}\\[6pt]
    \begin{itemize}[leftmargin=16pt, itemsep=4pt]
      \item thedotmack/claude-mem
      \item safishamsi/graphify
      \item Capture \& compress coding session context
      \item Codebases $\to$ queryable knowledge graphs
    \end{itemize}
  \end{minipage}\hfill
  \begin{minipage}[t]{0.23\linewidth}
    \colorbox{greenaccent!20}{\parbox{0.92\linewidth}{\centering\vspace{4pt}
      {\fontsize{26}{32}\selectfont\bfseries\color{greenaccent} Skill\\Distillation}\vspace{2pt}
    }}\\[6pt]
    \begin{itemize}[leftmargin=16pt, itemsep=4pt]
      \item \#1: andrej-karpathy-skills
      \item alchaincyf/nuwa-skill
      \item Package expert mental models as reusable AI skills
    \end{itemize}
  \end{minipage}
}

\end{tcbposter}
\end{document}

